mapper.sql:
WITH objRec AS( SELECT tmp1.REG_CODE, tmp1.VDATE, NVL(tmp1.actEndMDate,tmp1.MDate) MDATE FROM ( SELECT A.REG_CODE, A.VDATE, A.MDATE, B.MDATE AS actEndMDate, ROW_NUMBER() over( partition by A.REG_CODE ORDER BY B.STATUS DESC ,B.UPDATE_TIME DESC ) AS endStatusNo FROM CHB_PRD_BASEINFO A LEFT JOIN CHB_PRD_END_SUB B ON (A.REG_CODE = B.PROD_REGIST_CODE
#{orgCode,jdbcType=VARCHAR}
) WHERE A.STATUS != 'D' AND B.STATUS IN ('01','02') AND TO_DATE(TO_CHAR(A.VDATE, 'yyyy-MM-dd'), 'yyyy-MM-dd') <= TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd')
) tmp1 WHERE endStatusNo = 1 AND ( (actEndMDate is null AND MDATE > #{searchDate,jdbcType=DATE} AND TO_DATE(TO_CHAR(MDATE, 'yyyy-MM-dd'), 'yyyy-MM-dd') > TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') ) OR ( actEndMDate is not null AND TO_DATE(TO_CHAR(actEndMDate, 'yyyy-MM-dd'), 'yyyy-MM-dd') > TO_DATE(#{searchDate,jdbcType=VARCHAR},'yyyy-MM-dd') ) ) )
